CREATE TABLE IF NOT EXISTS users (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,password_hash VARCHAR(255) NOT NULL,role ENUM('admin','moderator','user') NOT NULL DEFAULT 'user',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS categories (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL UNIQUE,description VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS listings (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,category_id BIGINT UNSIGNED NOT NULL,title VARCHAR(120) NOT NULL,description TEXT NOT NULL,city VARCHAR(80) NOT NULL,price DECIMAL(14,2) NOT NULL DEFAULT 0,phone VARCHAR(25) NOT NULL,status ENUM('active','expired','blocked','archived') NOT NULL DEFAULT 'active',expires_at DATETIME NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE RESTRICT,INDEX listing_filter(category_id,city,status,expires_at),INDEX listing_owner(user_id),CHECK(price>=0)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS complaints (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,reason TEXT NOT NULL,status ENUM('open','approved','rejected') NOT NULL DEFAULT 'open',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,UNIQUE KEY one_complaint(user_id,listing_id),INDEX(status)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS moderation_decisions (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,complaint_id BIGINT UNSIGNED NOT NULL UNIQUE,moderator_id BIGINT UNSIGNED NOT NULL,outcome ENUM('approved','rejected') NOT NULL,note TEXT NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(complaint_id) REFERENCES complaints(id) ON DELETE RESTRICT,FOREIGN KEY(moderator_id) REFERENCES users(id) ON DELETE RESTRICT) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS attachments (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,listing_id BIGINT UNSIGNED NOT NULL,user_id BIGINT UNSIGNED NOT NULL,original_name VARCHAR(200) NOT NULL,stored_name CHAR(64) NOT NULL UNIQUE,mime VARCHAR(80) NOT NULL,size INT UNSIGNED NOT NULL,description VARCHAR(500) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(listing_id) REFERENCES listings(id) ON DELETE RESTRICT,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE RESTRICT,INDEX(listing_id)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS contact_messages (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,name VARCHAR(80) NOT NULL,email VARCHAR(190) NOT NULL,message TEXT NOT NULL,smtp_status ENUM('pending','sent','failed') NOT NULL DEFAULT 'pending',ip_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(ip_hash,created_at)) ENGINE=InnoDB;
CREATE TABLE IF NOT EXISTS auth_attempts (id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,ip_hash CHAR(64) NOT NULL,created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,INDEX(ip_hash,created_at)) ENGINE=InnoDB;
